package com.civileg.app.ui.compose.components

import androidx.annotation.StringRes
import androidx.compose.runtime.Composable
import androidx.compose.ui.res.stringResource
import com.civileg.app.R

/**
 * Display names for safety checks generated by the calculation engines.
 *
 * The engines name checks in English and other code matches on those names, so the
 * name stays as the key and only the text shown on screen is translated. A name that
 * is not listed is shown unchanged. A trailing " - Footing 1" style suffix is kept.
 */
private val checkNameResources: Map<String, Int> = mapOf(
    "OT FS" to R.string.check_ot_fs,
    "Sliding FS" to R.string.check_sliding_fs,
    "Bearing" to R.string.check_bearing,
    "Soil Bearing" to R.string.check_bearing,
    "Stem Flexure" to R.string.check_stem_flexure,
    "Shear" to R.string.check_shear,
    "One-Way Shear" to R.string.check_one_way_shear,
    "Punching Shear" to R.string.check_punching_shear,
    "Flexure Steel" to R.string.check_flexure_steel,
    "Strap Beam Shear" to R.string.check_strap_beam_shear,
    "Hoop Tension Stress" to R.string.check_hoop_tension,
    "Uplift Safety Factor" to R.string.check_uplift,
    "Wall Reinforcement Ratio" to R.string.check_wall_reinf_ratio,
    "Wall Shear" to R.string.check_wall_shear,
    "Wall Shear Capacity" to R.string.check_wall_shear,
    "Crack Width" to R.string.check_crack_width,
    "Crack Control (fs)" to R.string.check_crack_control
)

@Composable
fun localizedCheckName(name: String): String {
    val parts = name.split(" - ", limit = 2)
    val base = checkNameResources[parts[0]] ?: return name
    val head = stringResource(base)
    return if (parts.size == 2) "$head - ${parts[1]}" else head
}
